    "detail": "一、推荐内容\n深夜聊书环节，群友接连报出正在读的书：微若妮卡在读《小镇喧嚣》（\"感觉我下了班回家继续上班\"）；春日迟迟在读《战争、枪炮与选票》并吐槽作者\"都不忘吹一嘴，英国的反对党是最忠诚的反对党\"；同一位群友还提到赌博业研究著作《运气的诱饵》（\"那简直是把人榨干了整\"）与韩丁的《翻身》（\"在党史各种官方记忆里不会细写的角落\"）。\n\n二、核心价值与特点\n书单覆盖基层治理、比较政治、行业民族志与党史微观史，共同特点是从具体材料里看结构——与当晚\"用词会影响看事情的视角\"的讨论互为印证。\n\n三、适用场景或补充信息\n春日迟迟还分享了辨私货心得：\"作者不管怎样，都会夹带私货……现在开始留意细节，就觉得处处是私货。\"可作为大家选书时的通用提醒。",
