    "title": "《伟大的长征》夜读会：从剧里细节到将帅书单",
    "date": "2026-11-07",
    "category": "红色与读书",
    "climb": "【Z】西西：伟大的长征这个剧。拍得很细、很深，很好。",
    "keywords": [
      "伟大的长征",
      "党史细节",
      "回忆录书单",
      "重走长征路"
    ],
    "detail": "一、话题背景与起因\n晚上，群友们围绕电视剧《伟大的长征》聊出一场高质量的党史夜读会。\n\n二、主要观点与讨论详情\n西西注意到剧中黄轩饰演的干部被问到两位干部情况时突然卡壳的细节，蚂蚁窝点破：很多读过党史的人都未必知道刘z丹同志当时遭遇了什么，「革命都危急成这样，还在内斗」。西西赞这个剧「拍得很有自信，故意让基层战士表现出畏畏缩缩不敢说出内斗真相的感觉，让观众更有代入感」。AA昍补了一句史观：「小细节加引号是因为这个事一点都不小，但放在长征里面确实显得不大。」\n\n针对「新长征不如旧版」的论调，AA昍给出一段漂亮的政治觉悟分析：教员在遵义会议前深刻反思的就是「我的主张再正确，如果得不到别人的拥护和理解，也没有用」；新的《伟大的长征》让这么多群众看了感动、甚至组织线下重走长征路，「这不正是教员说的——长征是宣言书，长征是宣传队，长征是播种机吗？」非要跳出来说旧版更好的人，「无非就想向别人证明：还是我懂」。\n\n聊到肃反历史，来财感慨「当初肃反真的可怕，说杀就杀」「曾中生多可惜」，AA昍串起王鸣处理张的手下、张g焘吓坏投kmt的连锁反应；还好分享井冈山之行，「对于王佐和袁文才的遭遇也更加理性看待了——事实都藏在细节中」；AA昍则讲了贺z珍的心结：井冈山上带点政治联姻味道，亲缘一个接一个消失，弟弟被枪毙的事忍到陕北才提，「教员也只是叹气，说纪律没错」。\n\n精神层面的共鸣最热烈：呼吸自己「即使这样的苦日子，在毛选里也看不到任何抱怨和悲观」；点灯「每当遇到困难都会想，跟当年他们比起来一点都不算什么，然后就充满了希望」；u「苦不苦，想想红军两万五——小时候只当是个口号，现在才知道是真的」；鱼皮说看完剧，遇到问题会想「剧里的人们碰到这个问题，一定不会消沉，一定会积极、乐观地去解决」。AA昍则评「榜样的力量是无穷的」：听着有点唯心主义，但因为是教员说的，以教员为榜样，力量真的是无穷的。鱼皮回应：「原本我是一个看见才能相信的人，结果亲眼看到了这样一个相信因而看到的奇迹。」\n\n夜读会最后变成大型书单现场：毛周传记、聂r臻回忆录、《地球的红飘带》、王树增《长征》、朱d传、粟y回忆录、陈y文选、《红星照耀中国》、熊x晖《我的情报与外交生涯》、曾z回忆录、徐x前《历史的回忆》……AA昍强推粟y「军神，人品好，而且长得可爱」，来财补上「此去泉台招旧部，旌旗十万斩阎罗」（AA昍：「就这一句，把陈老总一辈子的诗歌才华抽掉1/3」），还有解放后粟y与妻子逛街、看着咖啡厅说「架两把机枪谁也别想过」的名场面。AA昍许下心愿：「粟的骨灰洒在战友们当年牺牲的几个不同的地方，我将来有机会要去一一拜访。」\n\n三、结论与启发\n看剧是入口，细节是钥匙：从一部剧进到党史，从党史进到回忆录，越了解越有感情——这大概就是「长征是宣传队、是播种机」在2026年的样子。",
    "conclusion": "评主旋律作品先讲政治觉悟：让群众看到、感动、愿意走近历史，就是宣传队和播种机。\n\n精神力量是真实存在的：从「看见才能相信」到「相信因而看到」。\n\n一份群友共创的党史书单，从传记到回忆录互相印证。",
