    "detail": "一、推荐内容\n AA昍在社保讨论的尾声给出一个极简的风向判断法：「都不用跟着国家政策走，你就跟着国家的税收走。国家在哪收税，说明哪能赚钱。」\n\n二、核心逻辑\n 论据是他观察自媒体行业多年得出的两个信号：2026年国家开始对年收入12万以上的自媒体收税，「一是说明自媒体一年赚12万是很容易的事了，至少有一半从业人员有机会达到，且有大数据支撑；二是行业从粗放转向精细，大批头部大V会因为不正规死掉，空出生态位给新人」。\n\n三、适用边界\n 「所有收税的方向里，有优惠的方向，那就是国家鼓励的，跟着干就完了。」边界也只有一条：「刑法里不让干的就不要干，多简单呀。」",
