    "detail": "一、推荐内容\n补剂讨论中，KonGyHaO贡献了两样东西：一份自己了解整理的《维生素用法》文档（群文件可取，他按这个吃法吃了好几年），以及一条省钱路线——「维生素我全部都是吃药店最便宜的 OTC 小白瓶，便宜划算，就是相比之下麻烦一点，一天要随餐吃好几次」。\n\n二、核心价值与特点\n文档是他按「找个吃法」实践数年的总结，「供大家参考」。群友的交叉验证更添说服力：小企鹅造屋在医院开到4块钱一盒的维D（绿盒双鲸），「医生说外面要卖六七十」「后来出去一看，真的」；牛奶趣多多补充维C同样是巨便宜级别；会计王小全🐰提醒一个坑：「复合维生素里的D一般都很少」，别指望一粒复合片解决所有。\n\n三、适用场景或补充信息\n适合想开始规律补剂又怕交智商税的同志：先查指标、缺啥补啥、买基础款；剂量问题（维D的2000iu/4000iu之辨）请参考当天健康话题的讨论与「第一责任人」原则。",
