    "climb": "【Y】犬八：日日种太阳时期卖文章，我还把文章全部截图保存了呢",
    "keywords": [
      "博客备份",
      "自媒体考古",
      "一手材料"
    ],
    "detail": "一、推荐内容\n考古之夜，群友追问当年「科学家种太阳」时期的文章。AA昍直接甩出备份链接——博客「丰镐」，并注明「大部分是免费的」，其中825号文章《所谓精英与无产》正是当年的自我剖析。犬八则亮出民间备份：当年把卖的文章全部截图保存，「现在去翻翻估计反动言论不少」哈哈哈。\n\n二、核心价值与特点\n对想理解「一个自由派头部大V如何完成立场转变」的同志，这是一手材料而非二手转述。当晚群里的金句总结也许更适合当入口：「都是黑历史，也是来时路。」Ps还贡献了自己的收藏夹金句：「房子是应该经常打扫的，不打扫就会积满了灰尘；脸是应该经常洗的，不洗也就会灰尘满面。」\n\n三、适用场景或补充信息\n搭配当晚讨论食用更佳：知识垄断、唯物史观、英语学习方法论，都能在旧文新读里找到对照。",
