    "detail": "一、推荐内容\n一场「求书」引发的群友共创书单。专业档（春日迟迟）：《魏晋之际的政治权力与家族网络》《隳三都：蒙古灭金围城史》、顾诚《明末农民战争史》《南明史》；轻量档：《三国不演义》、刘勃《失败者的春秋》《战国歧途》（附立场警告：读够100本历史书前谨慎入口）、南朝讲东晋门阀世家系列；通识档（豆子汇总）：《智能》《有毒的人》《先解决情绪，再解决问题》《汉末之变》《何以世界》等。入门友好档：蒙曼隋唐系列（讲堂汇总、可听书，小福仙推荐其红楼梦讲座）、 Cadet Oxton认证「有史料原文的现代汉语对照解释」。\n\n二、核心价值与特点\n书单自带「立场风险提示」与阅读次序建议：先主干（毛选/党史/正统史学）后支流，是本单与全网书单最大的不同。\n\n三、适用场景或补充信息\n另有GitHub高热度项目《HowToLiveBetter》高性价比人生指南（开源地址群里已发）；网页打不开的同志，群文件里有群友转存的PDF和HTML版——小福仙的批评也一并参考：「里面很多都是P话，网上不知道哪抓来的」，s补充「一看就是用ai整理的」。工具书单，取其框架即可。",
