    "detail": "一、推荐内容\n微若妮卡。晒出买到的毛选小卡，leon立刻提醒「假毛选」，AA昍鉴定其中一句「不是教员说的，明显是唯心主义」。正解随即登场：豆子推荐了群友自己做的卡牌——「里面的内容确保是毛选里的」；四只小猫没偷猪分享了电子版并报出名字：叫「问问毛选」。阿要偷猪？补充购买渠道：「毛选卡片可以买日日快团团里那个，良猫同志自己做的，很精美」。\n\n二、核心价值与特点\n内容保真是最大卖点：市面小卡常有「伪语录」混入（当场就鉴定出一例），群友自制的这套每张都可在毛选原文中定位。秋的使用体验：「毛选卡片是真的很好用，随手一拿就是看，能量蹭蹭涨」。u还给出鉴别方法：内容判断不出来时，「从语言习惯上也可以判断真假」。\n\n三、适用场景或补充信息\n适合放在工位/床头当随手翻：碎片时间抽一张，比刷手机健康；也适合当礼物转发给开始读书的同志。",
