    "detail": "一、话题背景与起因\n上午，Johnny分享了一条刚知道的史实：张g焘1924年就叛变过一次——被北洋政府抓捕后供出了80多名同志，其中包括李d钊；李d钊及时逃脱，另有40多名党员被牵连。这是1951年新中国清查敌伪档案时发现的。呼吸自己一句「畜牲啊」定下情绪，洋没偷猪则贴出群公告提醒「聊天涉及政治人物时，勿使用全名」——Johnny道歉：「刚看到这个史实，有点惊讶，就没忍住」。\n\n二、主要观点与讨论详情\n这条史料在深夜长谈里被AA昍接住并展开成三层：\n1. 叛变的根源早就有信号：「根源可能在这儿，张g焘1924年就已经叛变了革命，早就是个kmt军阀性质的人了」。结合白天《伟大的长征》剧终后的讨论，群友们的愤怒有了史实支点：来财「张太自私了，不把别人的命当命」、春日迟迟引王树增《长征》——李d在瑞金专门养了一群鸭子每天杀一只给他吃，还经常打骂妻子，有一次被领导人当面制止；「联想到他瞎指挥让我们牺牲了那么多人，很难不恨」。鱼皮的愤懑最有代表性：「最后还安享晚年，想想就血压高」。\n\n2. 苏军为什么配不上「人类新军」：AA昍给出一段重史料：「苏军是没有官兵平等概念的。伟大的长征里，李d为什么总是趾高气扬地让红军士兵给他擦靴子、端茶倒水、泡咖啡？甚至对组织安排嫁给他的『妻子』动不动就凌辱打骂……最后他离开时也是随意抛弃再没有联系过（这些在史料里都有，但没拍）」——结论：「苏军配不上人类新军的概念，全人类新军目前只有两支，中国的红军和后来的PLA」。他补充：李d晚年在苏联要求下还写了很多污蔑cpc和红军领导人的文章，「纯纯的狗逼」；而cpc厚道，「很多人只要死了，就不再追究了」。\n\n3. 群友的史料接力：我就偷猪搜出了李d两任妻子的后续——第一任萧y华不顾李d反对坚持参加抗大、上抗日前线，离婚后继续革命，建国后任湖南省交通厅办公室主任，1960年授大校军衔，是解放军首次授衔四位女大校之一；第二任女演员未能随李d去苏联，「终身未等到李d再回来」。春日迟迟再补王树增书里的细节：张g焘到了四川「吃得肥头大耳白白胖胖，完全就不是一路人」。AA昍把线索收束回源头：「张g焘1924年就已经叛变了革命」，春日迟迟接：「所以狱中八条每一条都是血的教训，全是活生生的例子……」鱼皮补了剧里的弹幕名场面：「每次李d一出场，弹幕全是『军事法庭』」，并给出组织态度的注解：「组织对一些犯了错误的同志，还是想『惩前毖后治病救人』吧」。\n\n三、争议焦点\nAA昍提到《伟大的长征》对共产国际和苏联的问题「没有展开讲」，如意如意随我心意共鸣「太克制了」；AA昍的解释是分寸：「主要群众理解不了，不能展开讲，讲多了，就成赫l晓夫那种自己拆自己台的傻逼了。过一百年可能就可以讲了」。\n\n四、结论与启发\n①立场败坏早有信号：1924年的叛变与后来的分裂一脉相承——看人看历史，要查底档；②对照结构最有力：同一段历史，萧y华的选择与李d的所作所为互为镜像；③「惩前毖后、治病救人」的宽厚是有边界的宽厚，不是无原则的原谅。",
    "conclusion": "立场败坏早有信号：1924年的叛变与后来的分裂一脉相承。\n\n全人类新军目前只有两支：中国的红军和后来的PLA。\n\n惩前毖后治病救人：宽厚有边界，历史有底档。",
