    "detail": "一、推荐内容\n《伟大的长征》收官后，春日迟迟分享了进阶书单：王树增《长征》——「写得很克制了，但字里行间真的很气愤」；书中细节扎心：李d在瑞金专门养了一群鸭子每天杀一只吃、经常家暴妻子被领导人当面制止；张g焘到四川后「吃得肥头大耳白白胖胖，完全就不是一路人」。\n\n二、核心价值与特点\n剧中没拍的部分，书里有：AA昍补充李d晚年在苏联撰写污蔑cpc文章的史料，以及张g焘1924年首次叛变供出80多名同志（含李d钊）的底档——「1951年新中国清查敌伪档案就发现的事」由Johnny爆出。春日迟迟点出书的价值锚点：「狱中八条每一条都是血的教训，全是活生生的例子」。\n\n三、适用场景或补充信息\n适合追完剧意犹未尽的同志；阅读搭配建议：正剧打底 → 王树增《长征》补细节 → 狱中八条对照读——从剧情到史实到教训，三层递进。",
