    "detail": "一、案情与围观\n自由人的联合体转发一个大学生被骗180万的防诈视频，群内第一波反应全是关注点清奇：谁没偷猪「《180万》」、偷猪摸狗赛博良民「还有180万」、liziwei「我的关注点也是180w啊……」。吉山偷猪来了一句歪理：家里有钱，怎么不算一种财富再分配呢——自由人的联合体立刻纠正：再分配也不能给骗子呀，哪怕设立信托，交个税交给人民，再分配使用呢；诈骗和偷窃是最恶劣的一种再分配形式了。\n\n二、反面教材价值论\n自由人的联合体给出了本场最正面的角度：这个大学生有一点好，上当受骗之后，愿意和警方合作，把自己的傻逼故事讲出来，当好反面教材，这是他真正的价值所在呀，毕竟是年轻人，进步空间还是有的——牺牲他一个，挽救/预防千万人，这比警方花180万的成本预算去做防诈宣传，可能效果要好。收官金句：「反诈宣传这个钱，我掏了！！！180w，够不够？不够再加！」\n\n三、家庭防骗方法论\nDecade贡献了正经干货：刚入学就有这么多钱，家庭应该是不错的；我爸以前也被骗过，银行卡异常转账短信期间我打电话过去问过——结论：你有家庭，平常信息就要共享一下，一般骗术骗不了一家人。liziwei自嘲收尾：论如果我要被骗180w需要几个环节——Decade：「假设失败，我没有180w[旺柴]」。",
    "conclusion": "反面教材的价值可以量化：一个180万的傻逼故事，胜过警方等额预算的防诈宣传。\n\n家庭信息共享是最便宜的防骗系统：一般骗术骗不了一家人。\n\n再分配有底线：交给骗子不是再分配，是最恶劣的转移。",
