    "detail": "一、问题背景\n发烧话题延展到扁桃体。南山漫竹自报家门：扁桃体三期，从小就因为这个发烧，想去割了都——后面补刀「三个，每个都有蚕豆大小」「父母双方都有，合成家族史上最强」，问了一圈医生都说割，就怕术后流血。\n\n二、割派与留派\nfreedobby是割派实证：小学6年级就割了——小时候老是发炎引起发烧，还引发了急性肾炎，医生说病灶不割还会引起其他器官的炎症反应，割了后呼吸道感染次数就少多了。留派的论据更感性：云野「割了更不好吧，有扁桃体在，它还能给你预警，割了你反而没法预警了」，还举了高中老师的反例（割完身体变差经常感冒）；XY总结成一句话：发炎的扁桃体也是某种保险丝。呆喵没睡醒提供家人反馈：割了后不适也会反映在身体其他部位——自己倒是靠短跑田径队把幼儿园起反反复复的扁桃体炎练好了。美丽心情123补了一个风险案例：前几天有一个男明星割扁桃体，术后感染心脏骤停走了。南山漫竹还记录了家族民间学说：等年纪大了，扁桃体它就不调皮了。\n\n三、发烧的本质\n顺带解决了开头的问题。呆喵没睡醒：发烧就是免疫系统启动高温无差别攻击模式了（类似化疗）。AA昍收束：无所谓为什么发烧，最终发烧的结果都是相似的——免疫系统疯狂加班，干了个大活，需要好好休息。",
