    "climb": "【Y】南山漫竹：没公园真不知道去哪做引体",
    "keywords": [
      "引体向上",
      "公园健身",
      "训练节奏"
    ],
    "detail": "一、公园是最伟大的发明\n南山漫竹安利广东的引体环境：出门就是公园，公司旁边也有，随时随地可以做，极大的降低了做引体的门槛；家里墙上装的那个用了几次不敢用了，幸得一公园大爷贴身指点——给我矫正握距，发力方式，效果立竿见影，真是差之毫厘，失之千里。此前他还闪过一次腰：以前太执着个数了。\n\n二、居家方案与晃杆警告\nAA昍给没公园的同志指路：落地架子不到200块，很便宜，平时还能晾衣服——XY吐槽「就怕一直晾衣服了……」。晃杆警告：看自己了，自己如果晃，那就会晃；有些人引体是晃上去的，那肯定不行，在家不安全——晃，容易受伤，年轻时无所谓，「等你老了就知道了」。南山漫竹承认坐到最后那一两个实在上不去就会忍不住晃。\n\n三、边际效益与节奏\n犬八贡献电饭煲模型：重量和数量的边际效益其实特别明显——100的电饭煲做80分，1000的做90分；拼命做又容易受伤还消耗精力，他自己练一个月嘎巴一下这里痛，休了一个月，一个月白练了。AA昍总结训练观：慢就是稳，稳就是快，伤一次得休半年，还不如每次少做两个。zw提示助力带会好很多；安东尼的季节波动也真实：夏天的时候天天出去能做10个，冬天了只能做三四个。",
