    "detail": "一、问题画像\n早晨南山漫竹交出体态真题：有没有一焦虑就不自觉耸肩，一天下来肩膀脖子痛的——并且自曝严重程度：耸肩才是我的日常模式，不耸肩是我的刻意模式。凌零共鸣：我不焦虑也耸肩，要注意到了才放松肩颈。\n\n二、肌肉机制与处方\n(ง •̀_•́)ง先指方向：练练背？背部肌肉紧了是不是能改善一点。南山漫竹反馈：有效果，拉完引体就好一些。小玉加一选项：射箭可以缓解，效果挺明显的。美丽心情123（拒接微信通话）贡献功法：八部金刚功的招式，左肝右肺如射雕；云端筑梦🐰推荐第八套广播体操——有用的，之前医生推荐的，活动活动筋骨。Unique惊喜找到组织：我还以为只有我最近心血来潮翻出来广播体操了，原来还有志同道合的。\n\n三、晚间专业续场\n晚上20%交出肌肉层面的完整处方：有可能是上斜方肌太强（紧张），或者对侧肌肉太弱——可以考虑用筋膜球放松上斜方，同时锻炼对侧肌肉，例如下斜方肌、前锯肌（稳定肩胛）、背阔肌这些，具体哪些肌肉还需同志自己去做下功课。南山漫竹收下：谢谢，我试试；陈小彼同步记笔记。",
    "conclusion": "耸肩不是习惯是肌力失衡：上斜方肌太强（紧张）或对侧太弱，处方=筋膜球放松+练下斜方/前锯肌/背阔肌。\n\n实证缓解菜单：引体有效、射箭明显、八部金刚功「左肝右肺如射雕」、第八套广播体操医生推荐。",
