    "detail": "一、院系补贴三条杠\n由读博话题引出的补贴考据，AA昍（中科院心理学背景）回忆当年上大课各院聊补贴的名场面：物理学院发的是防辐射费，一个月是1200；化学学院发的是防腐蚀费，一个月是1000；生物学院发的是防感染费，一个月是800——这些都是在财政部直接每学生发700补贴之外的。心理学穷就只有700，当时师兄师姐说应该发精神损失费，一个月1000。\n\n二、中科院待遇真相\n正面科普：中科院的硕博可不是覆盖学费的问题——首先中科院不收学费，其次不归教育部管所以学生补贴非常高，再次混个不错的导师、手里有横向课题或国家基金课题，一个月光是老师发的钱就能上千，加上七七八八月薪有可能5k起，比很多上班的还多。AA昍自己的账本：700中科院补贴+0院系补贴+300导师补贴（1篇中文补100、1篇英文补200）+项目奖金1000+横向加班费500，比一些本科同学的税后工资还高。配套往事：当年在4A实习，组长说读研没用，我说可是中科院不要学费，组长眼睛都亮了，当天就给我赶走了。\n\n三、傻博社会学\n对博士社会化的冷观察：中国人吃饱饭才几年啊，现实中的智人喜欢学习的多吗？筛选下来，什么人会读博啊——客观规律。但一旦想明白，进步巨大：能意识到博士社会化水平低的博士都进步巨大，意识不到就难。",
